enum class Role : AuthenticationRole { User, Admin, Pauser }

install(Authentication) {
    basic("auth-basic") { validate { creds -> UserIdPrincipal(creds.name) } }
        .withRoles { principal -> roleService.resolveRoles(principal.name) }   // server-side
}

routing {
    authenticateWith(roles = setOf(Role.Pauser, Role.Admin)) {
        post("/transfers/pause") { call.respond(HttpStatusCode.NoContent) }
    }
}
